export interface ErrorStackOptions {
  mode?: 'off' | 'string' | 'frames';
  normalizeNewlines?: boolean;
  trimLeadingWhitespace?: boolean;
  maxStackLines?: number;
  stripInternalFrames?: 'none' | 'node' | 'superjson' | 'node_and_superjson';
  redactPaths?: 'none' | 'basename' | 'strip_cwd';
  includeCauses?: 'none' | 'direct' | 'deep';
  maxCauseDepth?: number;
  sanitizeMessage?: boolean;
  classFilter?: string[];
}

export interface NormalizedErrorStackOptions {
  mode: 'off' | 'string' | 'frames';
  normalizeNewlines: boolean;
  trimLeadingWhitespace: boolean;
  maxStackLines?: number;
  stripInternalFrames: 'none' | 'node' | 'superjson' | 'node_and_superjson';
  redactPaths: 'none' | 'basename' | 'strip_cwd';
  includeCauses: 'none' | 'direct' | 'deep';
  maxCauseDepth: number;
  sanitizeMessage: boolean;
  classFilter: string[];
}

export function normalizeErrorStackOptions(input: unknown): NormalizedErrorStackOptions | undefined {
  if (!input || typeof input !== 'object' || Array.isArray(input)) return undefined;
  const o = input as ErrorStackOptions;
  const validLimit = o.maxStackLines === undefined || (Number.isInteger(o.maxStackLines) && o.maxStackLines > 0);
  const mode = validLimit && (o.mode === 'string' || o.mode === 'frames') ? o.mode : 'off';
  const stripInternalFrames = o.stripInternalFrames === 'node' || o.stripInternalFrames === 'superjson' || o.stripInternalFrames === 'node_and_superjson' ? o.stripInternalFrames : 'none';
  const redactPaths = o.redactPaths === 'basename' || o.redactPaths === 'strip_cwd' ? o.redactPaths : 'none';
  const includeCauses = (o.maxCauseDepth === undefined || Number.isInteger(o.maxCauseDepth)) && (o.includeCauses === 'direct' || o.includeCauses === 'deep') ? o.includeCauses : 'none';
  return {
    mode, normalizeNewlines: o.normalizeNewlines === true,
    trimLeadingWhitespace: o.trimLeadingWhitespace !== false,
    maxStackLines: validLimit ? o.maxStackLines : undefined,
    stripInternalFrames, redactPaths, includeCauses,
    maxCauseDepth: o.maxCauseDepth === undefined ? 16 : o.maxCauseDepth,
    sanitizeMessage: o.sanitizeMessage === true,
    classFilter: Array.isArray(o.classFilter) ? o.classFilter.filter((x): x is string => typeof x === 'string') : [],
  };
}

export function sanitizeMessage(message: string): string {
  return message.replace(/https?:\/\/[^\s<>"']+|[\w.+-]+@[\w.-]+\.[a-zA-Z]{2,}|\b(?:\d{1,3}\.){3}\d{1,3}\b/gi, '[redacted]');
}

export type Processor = (error: any) => any;

export class ErrorClassRegistry {
  private readonly processors = new Map<string, Processor>();

  register(name: string, fn: Processor): void {
    this.processors.set(name, fn);
  }

  has(name: string): boolean {
    return this.processors.has(name);
  }

  getProcessor(name: string): Processor | undefined {
    return this.processors.get(name);
  }
}

import { NormalizedErrorStackOptions } from './error-options.js';

export function normalizeStackNewlines(stack: string): string {
  return stack.replace(/\r\n?/g, '\n');
}

function lines(stack: string, options: NormalizedErrorStackOptions, frames: boolean): string[] {
  const text = options.normalizeNewlines ? normalizeStackNewlines(stack) : stack;
  let result = text.split('\n');
  if (options.trimLeadingWhitespace) result = result.map((line, i) => i ? line.replace(/^[^\S\r\n]+/, '') : line);
  const strip = () => {
    result = result.filter((line, i) => i === 0 || !((options.stripInternalFrames === 'node' || options.stripInternalFrames === 'node_and_superjson') && line.includes('node:internal')) && !((options.stripInternalFrames === 'superjson' || options.stripInternalFrames === 'node_and_superjson') && /src[\\/]((transformer|plainer|index)\.ts)/.test(line)));
  };
  const redact = () => {
    if (options.redactPaths === 'none') return;
    result = result.map(line => {
      if (options.redactPaths === 'strip_cwd') {
        const cwd = typeof process !== 'undefined' && typeof process.cwd === 'function' ? process.cwd() : '';
        return cwd ? line.split(cwd.replace(/[\\/]$/, '') + '/').join('').split(cwd.replace(/[\\/]$/, '') + '\\').join('') : line;
      }
      return line.replace(/(?:file:\/\/)?(?:[A-Za-z]:)?(?:[\\/][^\s():\\/]+)+/g, path => path.split(/[\\/]/).pop() || path);
    });
  };
  const limit = () => { if (options.maxStackLines !== undefined) result = result.slice(0, options.maxStackLines); };
  if (frames) { strip(); redact(); limit(); } else { redact(); limit(); strip(); }
  return result;
}

export function processStackString(stack: string, options: NormalizedErrorStackOptions): string {
  return lines(stack, options, false).join('\n');
}

export function processStackFrames(stack: string, options: NormalizedErrorStackOptions): { raw: string }[] {
  return lines(stack, options, true).map(raw => ({ raw }));
}

