import SuperJSON from './index.js';
import { processStackString, processStackFrames } from './error-stack.js';
import { sanitizeMessage } from './error-sanitizer.js';

function matchesError(v: Error, superJson: SuperJSON): boolean {
  const filter = superJson.errorStack?.classFilter;
  return !filter?.length || filter.includes(v.name);
}

function serializeError(v: Error, superJson: SuperJSON, depth = 0, seen = new Set<Error>()): any {
  const options = superJson.errorStack;
  const matches = matchesError(v, superJson);
  const result: any = { name: v.name, message: options?.sanitizeMessage && matches ? sanitizeMessage(v.message) : v.message };
  seen.add(v);
  if (!options) {
    if ('cause' in v) result.cause = v.cause;
    superJson.allowedErrorProps.forEach(prop => { result[prop] = (v as any)[prop]; });
  } else {
    superJson.allowedErrorProps.forEach(prop => {
      if (prop !== 'stack' && prop !== 'stackFrames' && prop !== 'cause' && prop !== 'errors') result[prop] = (v as any)[prop];
    });
    if (matches && typeof v.stack === 'string') {
      if (options.mode === 'string' && superJson.allowedErrorProps.includes('stack')) result.stack = processStackString(v.stack, options);
      if (options.mode === 'frames' && superJson.allowedErrorProps.includes('stackFrames')) result.stackFrames = processStackFrames(v.stack, options);
    }
    if (typeof AggregateError !== 'undefined' && v instanceof AggregateError) result.errors = v.errors;
    const cause = v.cause;
    const limit = options.includeCauses === 'direct' ? 1 : options.includeCauses === 'deep' ? options.maxCauseDepth : 0;
    if (depth < limit && cause instanceof Error && !seen.has(cause)) result.cause = serializeError(cause, superJson, depth + 1, seen);
  }
  return superJson.errorClassRegistry.getProcessor(v.name)?.(result) ?? result;
}

function deserializeError(v: any, superJson: SuperJSON): Error {
  const cause = v.cause && !(v.cause instanceof Error) && typeof v.cause === 'object' && typeof v.cause.name === 'string' && typeof v.cause.message === 'string' ? deserializeError(v.cause, superJson) : v.cause;
  const e = v.name === 'AggregateError' && typeof AggregateError !== 'undefined' ? new AggregateError(v.errors, v.message, { cause }) : new Error(v.message, { cause });
  e.name = v.name;
  e.stack = v.stack;
  if (v.stackFrames !== undefined) (e as any).stackFrames = v.stackFrames;
  superJson.allowedErrorProps.forEach(prop => { if (prop !== 'stackFrames' || v.stackFrames !== undefined) (e as any)[prop] = v[prop]; });
  return e;
}

